    """Return elements of the matrix in clockwise spiral order.
    Handles rectangular as well as jagged matrices by padding missing entries.
    """
    if not matrix:
        return []
    total = sum(len(row) for row in matrix)
    if total == 0:
        return []
    max_cols = max(len(row) for row in matrix)
    # Pad rows with None
    padded = [row + [None]*(max_cols - len(row)) for row in matrix]
    top, bottom = 0, len(padded)-1
    left, right = 0, max_cols-1
    result = []
    while top <= bottom and left <= right and len(result) < total:
        # top row
        for c in range(left, right+1):
            val = padded[top][c]
            if val is not None:
                result.append(val)
        top += 1
        if len(result) >= total: break
        # right column
        for r in range(top, bottom+1):
            val = padded[r][right]
            if val is not None:
                result.append(val)
        right -= 1
        if len(result) >= total: break
        if top <= bottom:
            for c in range(right, left-1, -1):
                val = padded[bottom][c]
                if val is not None:
                    result.append(val)
            bottom -= 1
            if len(result) >= total: break
        if left <= right:
            for r in range(bottom, top-1, -1):
                val = padded[r][left]
                if val is not None:
                    result.append(val)
            left += 1
    return result
