def solve(n):
    # Count primes strictly less than n (Lucy_Hedgehog method: primes <= n-1).
    m = int(n) - 1
    if m < 2:
        return 0
    r = isqrt(m)
    V = [m // i for i in range(1, r + 1)]
    V += list(range(V[-1] - 1, 0, -1))
    S = {v: v - 1 for v in V}
    for p in range(2, r + 1):
        if S[p] > S[p - 1]:  # p is prime
            sp = S[p - 1]
            p2 = p * p
            for v in V:
                if v < p2:
                    break
                S[v] -= S[v // p] - sp
    return S[m]
