def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles arbitrary iterables gracefully; non-iterable or containing non-comparable items returns 0.
    """
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []
    for x in iterator:
        # Ensure the element is comparable; if not, skip.
        try:
            # bisect works with any orderable type
            idx = bisect.bisect_left(tails, x)
        except Exception:
            return 0
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

