    # Count number of islands (4-directionally connected 1s) in the grid.
    if not grid:
        return 0
    rows = len(grid)
    # handle possible jagged grid by using per-row lengths
    visited = set()
    def neighbors(r,c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows:
                # ensure column index within that row's length
                if 0 <= nc < len(grid[nr]):
                    yield nr, nc
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r,c) not in visited:
                count += 1
                # BFS/DFS
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr,cc) in visited:
                        continue
                    visited.add((cr,cc))
                    for nr, nc in neighbors(cr, cc):
                        if grid[nr][nc] == 1 and (nr,nc) not in visited:
                            stack.append((nr,nc))
    return count

