def solve(n, edges):
    """Return lexicographically smallest topological ordering of DAG with n nodes 0..n-1.
    If a cycle exists, return [] .
    """
    from heapq import heappush, heappop
    # Build adjacency list and in-degree counts
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        adj[a].append(b)
        indeg[b] += 1
    heap = []
    for i in range(n):
        if indeg[i]==0:
            heappush(heap,i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v]==0:
                heappush(heap,v)
    if len(order)!=n:
        return []
    return order

