    """Return True if *s* is a valid IPv4 address.
    The address must consist of exactly four decimal numbers separated by dots.
    Each number must be between 0 and 255 inclusive, and must not contain leading zeros
    (except the single digit "0").
    """
    parts = s.split('.')
