def solve(coins, amount):
    # Fewest coins summing to amount: BFS over reachable sums, one coin per layer.
    if amount == 0:
        return 0
    if amount < 0:
        return -1
    cs = {c for c in coins if c > 0}
    if not cs:
        return -1
    seen = [False] * (amount + 1)
    seen[0] = True
    frontier = [0]
    steps = 0
    while frontier:
        steps += 1
        nxt = []
        for a in frontier:
            for c in cs:
                na = a + c
                if na == amount:
                    return steps
                if na < amount and not seen[na]:
                    seen[na] = True
                    nxt.append(na)
        frontier = nxt
    return -1

