def solve(grid):
    """Count the number of islands (connected groups of 1s) in a 2D grid.
    Connectivity is 4-directional (up, down, left, right).
    Handles empty grid and non-rectangular rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = max((len(row) for row in grid), default=0)
    visited = [[False] * len(row) for row in grid]
    def neighbors(r, c):
        # up
        if r > 0 and c < len(grid[r-1]):
            yield r-1, c
        # down
        if r + 1 < rows and c < len(grid[r+1]):
            yield r+1, c
        # left
        if c > 0:
            yield r, c-1
        # right
        if c + 1 < len(grid[r]):
            yield r, c+1
    islands = 0
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 1 and not visited[r][c]:
                islands += 1
                # flood fill
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for nr, nc in neighbors(cr, cc):
                        if not visited[nr][nc] and grid[nr][nc] == 1:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
    return islands

