def solve(s):
    """Return True if brackets in s are balanced.
    Considers parentheses (), square brackets [], and curly braces {}.
    Ignores all other characters.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        else:
            # ignore other characters
            continue
    return not stack

def solve(a: list) -> list:
    a = list(a)
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return a

