    """Return the determinant of a square integer matrix.
    An empty matrix has determinant 1.
    Uses exact rational arithmetic (Fraction) to avoid floating point errors.
    """
    from fractions import Fraction
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a copy as Fractions
    a = [[Fraction(x) for x in row] for row in matrix]
    sign = 1
    for i in range(n):
        # Find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            sign *= -1
        # Eliminate below
        pivot_val = a[i][i]
        for j in range(i + 1, n):
            factor = a[j][i] / pivot_val
            if factor != 0:
                for k in range(i, n):
                    a[j][k] -= factor * a[i][k]
    # Determinant is product of diagonal times sign
    det = sign
    for i in range(n):
        det *= a[i][i]
    # det is Fraction, should be integer
